<template>
  <div class="page-heading"><div><div class="eyebrow">COMMUNITY</div><h1>群聊管理</h1><p>管理各 QQ 账号关联群聊、成员、群聊策略和群管理操作</p></div><div class="heading-actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button type="primary" :icon="Connection" @click="syncDialog=true">同步群列表</el-button></div></div>
  <section class="surface resource-surface"><div class="resource-toolbar"><div class="filter-row"><el-input v-model="keyword" clearable placeholder="搜索群名 / 群号" :prefix-icon="Search" @keyup.enter="load(1)"/><el-select v-model="accountFilter" clearable placeholder="筛选 QQ 账号" @change="load(1)"><el-option v-for="a in accounts" :key="a.id" :label="`${a.name} · ${a.qq_number||'未登录'}`" :value="a.id"/></el-select><el-button :icon="Search" @click="load(1)">查询</el-button></div></div>
  <el-table v-loading="loading" :data="groups" row-key="id" stripe empty-text="暂无群聊：把机器人拉进群并在群里 @ 它发一条消息，群会自动建档"><el-table-column prop="group_number" label="群号" width="115"/><el-table-column prop="name" label="群名称" min-width="165"/><el-table-column prop="account_name" label="绑定账号" width="130"/><el-table-column prop="member_count" label="成员" width="85"/><el-table-column label="AI 问答" width="90"><template #default="s"><el-tag :type="s.row.settings?.ai_enabled?'success':'info'" effect="dark" size="small">{{s.row.settings?.ai_enabled?'启用':'关闭'}}</el-tag></template></el-table-column><el-table-column label="审核" width="95"><template #default="s">{{modeLabel(s.row.settings?.moderation_mode)}}</template></el-table-column><el-table-column prop="last_synced_at" label="最后同步" width="165"><template #default="s">{{formatDate(s.row.last_synced_at)}}</template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="s"><el-button link type="primary" @click="openMembers(s.row)">成员</el-button><el-button link type="primary" @click="openSettings(s.row)">策略</el-button><el-dropdown @command="(cmd:string)=>groupAction(cmd,s.row)"><el-button link type="warning">管理操作<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="ban_all">开启全体禁言</el-dropdown-item><el-dropdown-item command="unban_all">解除全体禁言</el-dropdown-item><el-dropdown-item command="set_announcement">发布群公告</el-dropdown-item><el-dropdown-item command="set_group_name">修改群名称</el-dropdown-item><el-dropdown-item command="sync">同步群成员</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table>
  <div class="pagination-wrap"><span>共 {{total}} 个群聊</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[10,20,50]" layout="sizes,prev,pager,next" @current-change="load" @size-change="load(1)"/></div></section>
  <el-dialog v-model="membersDialog" :title="`群成员 · ${activeGroup?.name||activeGroup?.group_number||''}`" width="min(920px,calc(100vw - 28px))"><div class="member-toolbar"><el-input v-model="memberKeyword" clearable placeholder="搜索昵称或 QQ 号" :prefix-icon="Search" @keyup.enter="loadMembers(1)"/><el-button :icon="Refresh" @click="syncMembers">同步成员</el-button></div><el-table v-loading="membersLoading" :data="members" stripe><el-table-column prop="user_id" label="QQ 号" width="125"/><el-table-column prop="nickname" label="昵称" min-width="150"/><el-table-column prop="card" label="群名片" min-width="140"/><el-table-column prop="role" label="身份" width="90"><template #default="s">{{roleLabel(s.row.role)}}</template></el-table-column><el-table-column prop="warn_count" label="警告" width="75"/><el-table-column label="标记" width="145"><template #default="s"><el-tag v-if="s.row.is_blacklisted" type="danger" effect="dark" size="small">黑名单</el-tag><el-tag v-else-if="s.row.is_whitelisted" type="success" effect="dark" size="small">白名单</el-tag><span v-else>—</span></template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="s"><el-dropdown @command="(cmd:string)=>memberAction(cmd,s.row)"><el-button link type="primary">管理<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="mute">禁言 10 分钟</el-dropdown-item><el-dropdown-item command="unmute">解除禁言</el-dropdown-item><el-dropdown-item command="set_card">设置群名片</el-dropdown-item><el-dropdown-item command="kick" divided>踢出成员</el-dropdown-item><el-dropdown-item command="set_admin">设置管理员</el-dropdown-item><el-dropdown-item command="unset_admin">取消管理员</el-dropdown-item><el-dropdown-item command="blacklist">切换黑名单</el-dropdown-item><el-dropdown-item command="whitelist">切换白名单</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table><div class="pagination-wrap"><span>共 {{memberTotal}} 位成员</span><el-pagination v-model:current-page="memberPage" v-model:page-size="memberPageSize" :total="memberTotal" :page-sizes="[20,50,100]" layout="sizes,prev,pager,next" @current-change="loadMembers" @size-change="loadMembers(1)"/></div></el-dialog>
  <el-dialog v-model="settingsDialog" title="群聊独立策略" width="min(600px,calc(100vw - 28px))"><el-form :model="settings" label-position="top"><div class="settings-grid"><el-form-item label="启用群聊 AI"><el-switch v-model="settings.ai_enabled"/></el-form-item><el-form-item label="必须 @机器人 才回复"><el-switch v-model="settings.require_at_for_ai"/></el-form-item><el-form-item label="自动管理模式"><el-select v-model="settings.moderation_mode"><el-option label="关闭" value="off"/><el-option label="普通" value="normal"/><el-option label="严格" value="strict"/></el-select></el-form-item><el-form-item label="每分钟频率限制"><el-input-number v-model="settings.rate_limit_per_minute" :min="0" :max="500"/></el-form-item><el-form-item label="AI 模型 ID"><el-input-number v-model="settings.ai_model_id" :min="1" placeholder="留空使用默认模型"/></el-form-item><el-form-item label="上下文消息条数"><el-input-number v-model="settings.ai_context_limit" :min="1" :max="50"/></el-form-item></div><el-form-item label="群聊专属提示词"><el-input v-model="settings.ai_prompt" type="textarea" :rows="3" placeholder="可定义该群 AI 的角色与行为"/></el-form-item><el-form-item label="违禁关键词（JSON 数组）"><el-input v-model="bannedWordsText" type="textarea" :rows="2" placeholder='["广告词","敏感词"]'/></el-form-item><el-form-item label="入群欢迎模板"><el-input v-model="settings.welcome_template" type="textarea" :rows="2"/></el-form-item><el-form-item label="启用入群欢迎"><el-switch v-model="settings.welcome_enabled"/></el-form-item></el-form><template #footer><el-button @click="settingsDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveSettings">保存策略</el-button></template></el-dialog>
  <el-dialog v-model="syncDialog" title="同步群聊列表" width="min(450px,calc(100vw - 28px))"><el-form-item label="选择 QQ 账号"><el-select v-model="syncAccountId" style="width:100%"><el-option v-for="a in accounts" :key="a.id" :label="`${a.name} · ${a.qq_number||'未登录'} · ${a.runtime_state==='online'?'在线':'离线'}`" :value="a.id" :disabled="a.runtime_state!=='online'"/></el-select></el-form-item><template #footer><el-button @click="syncDialog=false">取消</el-button><el-button type="primary" :loading="syncing" :disabled="!syncAccountId" @click="syncGroups">开始同步</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowDown, Connection, Refresh, Search } from '@element-plus/icons-vue'
import { api } from '../api'
const groups=ref<any[]>([]),accounts=ref<any[]>([]),members=ref<any[]>([]),loading=ref(false),membersLoading=ref(false),saving=ref(false),syncing=ref(false),membersDialog=ref(false),settingsDialog=ref(false),syncDialog=ref(false),activeGroup=ref<any>(),page=ref(1),pageSize=ref(20),total=ref(0),memberPage=ref(1),memberPageSize=ref(20),memberTotal=ref(0),memberKeyword=ref(''),keyword=ref(''),accountFilter=ref<number>(),syncAccountId=ref<number>(),bannedWordsText=ref(''),settings=reactive<any>({})
async function load(p?:number){if(p)page.value=p;loading.value=true;try{const {data}=await api.get('/groups',{params:{page:page.value,page_size:pageSize.value,keyword:keyword.value||undefined,account_id:accountFilter.value||undefined}});groups.value=data.items||[];total.value=data.total||0}finally{loading.value=false}}
async function loadMembers(p?:number){if(p)memberPage.value=p;if(!activeGroup.value)return;membersLoading.value=true;try{const {data}=await api.get(`/groups/${activeGroup.value.id}/members`,{params:{page:memberPage.value,page_size:memberPageSize.value,keyword:memberKeyword.value||undefined}});members.value=data.items||[];memberTotal.value=data.total||0}finally{membersLoading.value=false}}
async function openMembers(group:any){activeGroup.value=group;membersDialog.value=true;memberPage.value=1;await loadMembers()}
function openSettings(group:any){activeGroup.value=group;Object.assign(settings,{ai_enabled:false,ai_model_id:null,ai_prompt:'',require_at_for_ai:true,ai_context_limit:12,welcome_enabled:false,welcome_template:'',member_change_notify:true,moderation_mode:'off',banned_words:[],rate_limit_per_minute:30,max_repeat_chars:4,auto_warn_threshold:3,auto_mute_seconds:600,auto_kick:false,announcement:'',...(group.settings||{})});bannedWordsText.value=JSON.stringify(settings.banned_words||[],null,2);settingsDialog.value=true}
async function saveSettings(){let banned:any;try{banned=JSON.parse(bannedWordsText.value||'[]');if(!Array.isArray(banned))throw new Error()}catch{ElMessage.error('违禁关键词必须是合法 JSON 数组');return}saving.value=true;try{await api.put(`/groups/${activeGroup.value.id}/settings`,{...settings,banned_words:banned});ElMessage.success('群聊策略已保存');settingsDialog.value=false;await load()}finally{saving.value=false}}
async function syncMembers(){if(!activeGroup.value)return;membersLoading.value=true;try{const {data}=await api.post(`/groups/${activeGroup.value.id}/sync`);ElMessage.success(data.detail||'同步完成');await loadMembers()}finally{membersLoading.value=false}}
async function syncGroups(){syncing.value=true;try{const {data}=await api.post(`/groups/sync/${syncAccountId.value}`);ElMessage.success(data.detail||'同步完成');syncDialog.value=false;await load()}finally{syncing.value=false}}
async function groupAction(action:string,g:any){if(action==='sync'){activeGroup.value=g;await syncMembers();return}if(action==='set_announcement'||action==='set_group_name'){try{const {value}=await ElMessageBox.prompt(action==='set_announcement'?'输入群公告内容':'输入新的群名称',action==='set_announcement'?'发布群公告':'修改群名称',{inputType:action==='set_announcement'?'textarea':'text',inputPlaceholder:action==='set_announcement'?'群公告':'群名称'});await api.post(`/groups/${g.id}/action`,{action,value});ElMessage.success(action==='set_announcement'?'群公告已发布':'群名称已更新');await load()}catch{}return}try{await ElMessageBox.confirm(action==='ban_all'?'开启全体禁言？':'解除全体禁言？','确认操作',{type:'warning'});const {data}=await api.post(`/groups/${g.id}/action`,{action});ElMessage.success(data.message||'操作已完成')}catch{}}
async function memberAction(action:string,m:any){const g=activeGroup.value;if(action==='blacklist'||action==='whitelist'){const body=action==='blacklist'?{is_blacklisted:!m.is_blacklisted}:{is_whitelisted:!m.is_whitelisted};const {data}=await api.post(`/groups/${g.id}/members/${m.user_id}/flags`,body);ElMessage.success('成员标记已更新');Object.assign(m,data);return}let value:any,body:any={action,user_id:m.user_id};if(action==='mute')body.duration_seconds=600;if(action==='set_card'){try{const r=await ElMessageBox.prompt('输入新的群名片','设置群名片',{inputValue:m.card||m.nickname||''});value=r.value}catch{return}body.value=value}if(action==='kick'){try{await ElMessageBox.confirm(`确定将 ${m.nickname||m.user_id} 移出群聊？`,'确认踢人',{type:'warning'})}catch{return}}if(action==='set_admin'||action==='unset_admin'){try{await ElMessageBox.confirm(action==='set_admin'?'确认设置该成员为管理员？':'确认取消该成员管理员？','确认操作',{type:'warning'})}catch{return}}try{const {data}=await api.post(`/groups/${g.id}/action`,body);ElMessage.success(data.message||'操作已完成');if(action==='kick')await loadMembers()}catch{}}
function formatDate(v:string){return v?new Date(v).toLocaleString('zh-CN'):'—'}
function modeLabel(v:string){return ({off:'关闭',normal:'普通',strict:'严格'} as any)[v]||'关闭'}
function roleLabel(v:string){return ({owner:'群主',admin:'管理员',member:'成员'} as any)[v]||v}
onMounted(async()=>{const [a]=await Promise.all([api.get('/accounts'),load()]);accounts.value=a.data;syncAccountId.value=accounts.value.find((x:any)=>x.runtime_state==='online')?.id})
</script>
<style scoped>
.resource-surface{padding:0;overflow:hidden;border-radius:14px;background:rgba(13,19,32,0.75);backdrop-filter:blur(16px);border:1px solid rgba(56,75,110,0.35);box-shadow:0 12px 35px rgba(0,0,0,0.4)}
.resource-toolbar{padding:16px 20px;border-bottom:1px solid rgba(56,75,110,0.35);background:rgba(16,24,40,0.4)}
.filter-row,.heading-actions,.member-toolbar{display:flex;align-items:center;gap:10px}
.filter-row .el-input{width:260px}
.filter-row .el-select{width:220px}
.pagination-wrap{display:flex;align-items:center;justify-content:space-between;padding:14px 20px;color:#8c9cb6;font-size:11px;border-top:1px solid rgba(56,75,110,0.25);background:rgba(16,24,40,0.25)}
.member-toolbar{justify-content:flex-end;margin-bottom:14px}
.member-toolbar .el-input{max-width:280px}
.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}
.settings-grid .el-select,.settings-grid .el-input-number{width:100%}
.page-heading{gap:12px}
@media(max-width:700px){
  .filter-row{flex-wrap:wrap}
  .filter-row .el-input,.filter-row .el-select{width:100%}
  .pagination-wrap{flex-wrap:wrap;gap:10px}
  .page-heading{align-items:flex-start}
  .heading-actions{flex-direction:column}
  .settings-grid{grid-template-columns:1fr}
}
</style>
